/**
 * AP-QA-03: the options of true/false quiz questions follow the interface language — "True"/"False" in English,
 * "Verdadero"/"Falso" in Spanish — everywhere they are shown (run through e2e/run.sh against the production build and
 * the demo seed). They are generated by the system: the canonical answers are the option ids "true" and "false" (the
 * stored text is the English default), so only the label changes; stored questions, answers, attempts and grades do not.
 * - Student attempts in English and Spanish at 390 and 1440 px, answered and submitted with the keyboard only; the
 *   server grades True and False answers by their canonical ids.
 * - A language switch while a question is shown relabels the options and keeps the selection.
 * - Instructor authoring and Design Team review show the same labels; the stored answer key is unchanged.
 * - Released feedback and the staff attempt detail, and attempts saved before this change (the demo seed's).
 * Fixtures: a dedicated course (isolatedCourse) whose enrollments are made inactive afterwards; the seeded attempts are
 * only read. Prompts and titles contain no phrase from either interface catalog.
 */
import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { after, before, describe, it } from 'node:test';
import type { Browser, Page } from 'playwright';
import { apiGet, apiWrite, BASE, context, isolatedCourse, launch, leaks, MESSAGES, settle, switchLocale, type Locale, type Role } from './support.ts';

const TAG = randomBytes(3).toString('hex');
/** The expected presentation (AP-QA-03), stated here rather than read from the catalog under test. */
const LABELS = { en: ['True', 'False'], es: ['Verdadero', 'Falso'] } as const;
const PROMPT_TRUE = `TF ${TAG}: kappa comes before lambda`;
const PROMPT_FALSE = `TF ${TAG}: lambda comes before kappa`;

let browser: Browser;
let courseId: string;
let sectionId: string;
let cleanup: () => Promise<void> = async () => undefined;

type Option = { id: string; text: string; isCorrect?: boolean };
type ResultQuestion = { prompt: string; options: Option[]; selectedOptionIds: string[]; isCorrect: boolean | null; awardedPoints: number | null };

async function open(role: Role, locale: Locale, path: string, width = 1440): Promise<Page> {
  const page = await (await context(browser, locale, role, { width })).newPage();
  await page.goto(`${BASE}${path}`);
  await settle(page);
  return page;
}
const focused = (page: Page) =>
  page.evaluate(() => {
    const el = document.activeElement as HTMLInputElement | null;
    return { tag: el?.tagName ?? '', type: el?.type ?? null, text: (el?.labels?.[0]?.innerText ?? el?.innerText ?? '').trim(), checked: el?.checked ?? null };
  });
async function press(page: Page, key: string) {
  await page.keyboard.press(key);
  return focused(page);
}
const optionLabels = (page: Page, question: number) => page.locator('main fieldset').nth(question).locator('label').allInnerTexts();

/** An approved quiz with two true/false questions: the first is true, the second false. */
async function approvedQuiz(title: string, attemptLimit = 1): Promise<string> {
  const quiz = await apiWrite<{ id: string }>('instructor', 'POST', `/courses/${courseId}/sections/${sectionId}/activities`, { type: 'quiz', title, attemptLimit, showFeedback: true });
  for (const [prompt, correctAnswer] of [[PROMPT_TRUE, true], [PROMPT_FALSE, false]] as const) {
    await apiWrite('instructor', 'POST', `/courses/${courseId}/activities/${quiz.id}/questions`, { type: 'true_false', prompt, points: 1, correctAnswer });
  }
  await apiWrite('instructor', 'POST', `/courses/${courseId}/activities/${quiz.id}/submit`, {});
  await apiWrite('reviewer', 'POST', `/courses/${courseId}/activities/${quiz.id}/review`, { decision: 'approve' });
  return quiz.id;
}

before(async () => {
  browser = await launch();
  ({ courseId, sectionId, cleanup } = await isolatedCourse(`ZZ-QA03-TF-${TAG}`, `True false fixture course ${TAG}`, [
    ['instructor', 'instructor'],
    ['reviewer', 'design_team'],
    ['student', 'student'],
  ]));
});
after(async () => {
  await browser?.close();
  await cleanup();
});

describe('true/false options follow the interface language (AP-QA-03)', () => {
  const runs = [
    { locale: 'en', width: 390, choose: ['true', 'false'] },
    { locale: 'en', width: 1440, choose: ['false', 'true'] },
    { locale: 'es', width: 390, choose: ['true', 'true'] },
    { locale: 'es', width: 1440, choose: ['false', 'false'] },
  ] as const;
  for (const run of runs) {
    it(`student, ${run.locale.toUpperCase()} at ${run.width} px: labels, keyboard-only answers and submission, grading by canonical value`, async () => {
      const labels = LABELS[run.locale];
      const q = MESSAGES[run.locale].quiz;
      const quizId = await approvedQuiz(`QA03 tf fixture ${run.locale} ${run.width} ${TAG}`);
      const page = await open('student', run.locale, `/courses/${courseId}/activities/${quizId}`, run.width);
      await page.getByRole('button', { name: q.student.start }).click();
      await page.waitForURL(/\/attempts\//);
      await page.waitForFunction(() => document.activeElement?.tagName === 'H1');
      for (const question of [0, 1]) assert.deepEqual(await optionLabels(page, question), [...labels], `question ${question + 1} options`);
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      assert.ok(overflow <= 0, `${overflow} px wider than the screen`);

      // Keyboard only: Tab into each question, Space selects the first option, ArrowDown moves to the second.
      for (const value of run.choose) {
        let focus = await press(page, 'Tab');
        assert.deepEqual([focus.type, focus.text], ['radio', labels[0]]);
        focus = await press(page, 'Space');
        if (value === 'false') focus = await press(page, 'ArrowDown');
        assert.deepEqual([focus.text, focus.checked], [labels[value === 'true' ? 0 : 1], true]);
      }
      await press(page, 'Tab');
      assert.equal((await press(page, 'Tab')).text, q.attempt.submit);
      assert.equal((await press(page, 'Enter')).text, q.attempt.confirmSubmit);
      await page.keyboard.press('Enter');
      await page.getByRole('heading', { name: q.attempt.recordedHeading }).waitFor();
      assert.deepEqual(await leaks(page, run.locale), []);

      // The server stored the canonical values and graded them; its stored options are unchanged.
      const attemptId = page.url().split('/attempts/')[1]!.split(/[?#]/)[0]!;
      const stored = await apiGet<{ questions: Array<{ options: Option[]; selectedOptionIds: string[] }> }>('student', `/courses/${courseId}/attempts/${attemptId}`);
      assert.deepEqual(stored.questions.map((question) => question.selectedOptionIds), run.choose.map((value) => [value]));
      for (const question of stored.questions) assert.deepEqual(question.options, [{ id: 'true', text: 'True' }, { id: 'false', text: 'False' }]);
      const result = await apiGet<{ score: number; questions: ResultQuestion[] }>('instructor', `/courses/${courseId}/activities/${quizId}/results/${attemptId}`);
      const expected = [run.choose[0] === 'true', run.choose[1] === 'false'];
      assert.deepEqual(result.questions.map((question) => question.isCorrect), expected, 'True and False are graded by their canonical ids');
      assert.deepEqual(result.questions.map((question) => question.awardedPoints), expected.map((correct) => (correct ? 1 : 0)));
      assert.equal(result.score, expected.filter(Boolean).length);
      await page.context().close();
    });
  }

  it('a language switch while a question is shown relabels the options and keeps the selection', async () => {
    const quizId = await approvedQuiz(`QA03 tf switch ${TAG}`);
    const page = await open('student', 'es', `/courses/${courseId}/activities/${quizId}`);
    await page.getByRole('button', { name: MESSAGES.es.quiz.student.start }).click();
    await page.waitForURL(/\/attempts\//);
    await page.locator('main fieldset').first().waitFor();
    const first = page.locator('main fieldset').first();
    await first.getByLabel(LABELS.es[1], { exact: true }).check();
    await switchLocale(page, 'en');
    for (const question of [0, 1]) assert.deepEqual(await optionLabels(page, question), [...LABELS.en]);
    assert.equal(await first.getByLabel(LABELS.en[1], { exact: true }).isChecked(), true, 'the selection is kept');
    await switchLocale(page, 'es');
    for (const question of [0, 1]) assert.deepEqual(await optionLabels(page, question), [...LABELS.es]);
    assert.equal(await first.getByLabel(LABELS.es[1], { exact: true }).isChecked(), true);
    assert.deepEqual(await leaks(page, 'es'), []);
    await page.context().close();
  });

  it('instructor authoring and Design Team review show the labels in the interface language; the stored key is unchanged', async () => {
    const quiz = await apiWrite<{ id: string }>('instructor', 'POST', `/courses/${courseId}/sections/${sectionId}/activities`, { type: 'quiz', title: `QA03 tf authoring ${TAG}`, attemptLimit: 1 });
    const path = `/courses/${courseId}/activities/${quiz.id}`;
    const bankOptions = (page: Page) => page.locator('section[aria-labelledby="questions-heading"] ol > li ul > li').allInnerTexts();
    const expectBank = async (page: Page, locale: Locale) => {
      const items = (await bankOptions(page)).map((item) => item.replace(/\s+/g, ' ').trim());
      const [yes, no] = LABELS[locale];
      assert.equal(items.length, 2, items.join(' | '));
      assert.equal(items[0], `• ${yes}`);
      assert.ok(items[1]!.startsWith(`✓ ${no}`), `${items[1]} marks ${no} as the correct answer`);
    };

    const instructor = await open('instructor', 'es', path);
    await instructor.locator('#question-type').selectOption('true_false');
    await instructor.locator('#question-prompt').fill(PROMPT_FALSE);
    await instructor.locator('#question-tf-answer').selectOption('false');
    await instructor.getByRole('button', { name: MESSAGES.es.quiz.form.submit, exact: true }).click();
    await instructor.getByText(MESSAGES.es.quiz.bank.added).waitFor();
    await expectBank(instructor, 'es');
    await switchLocale(instructor, 'en');
    await expectBank(instructor, 'en');
    await switchLocale(instructor, 'es');
    const stored = await apiGet<{ items: Array<{ type: string; options: Option[] }> }>('instructor', `${path}/questions`);
    assert.deepEqual(stored.items.map((question) => [question.type, question.options]), [
      ['true_false', [{ id: 'true', text: 'True', isCorrect: false }, { id: 'false', text: 'False', isCorrect: true }]],
    ], 'the stored question keeps its canonical options and answer key');
    await instructor.locator('section[aria-labelledby="review-heading"]').getByRole('button', { name: MESSAGES.es.content.review.submit }).click();
    await instructor.getByText(MESSAGES.es.content.review.submitted).waitFor();
    await instructor.context().close();

    const reviewer = await open('reviewer', 'es', path);
    await expectBank(reviewer, 'es');
    await reviewer.locator('section[aria-labelledby="review-heading"]').getByRole('button', { name: MESSAGES.es.content.review.approve, exact: true }).click();
    await reviewer.getByText(MESSAGES.es.content.review.approved).waitFor();
    await switchLocale(reviewer, 'en');
    await expectBank(reviewer, 'en');
    await reviewer.context().close();
  });

  it('released feedback and the staff attempt detail use the interface language', async () => {
    const quizId = await approvedQuiz(`QA03 tf feedback ${TAG}`);
    const attempt = await apiWrite<{ id: string; questions: Array<{ questionId: string }> }>('student', 'POST', `/courses/${courseId}/activities/${quizId}/attempts`);
    // True to both: the first answer is correct, the second is not.
    await apiWrite('student', 'POST', `/courses/${courseId}/attempts/${attempt.id}/submit`, { answers: attempt.questions.map((question) => ({ questionId: question.questionId, selectedOptionIds: ['true'] })) });
    await apiWrite('instructor', 'POST', `/courses/${courseId}/activities/${quizId}/grades/release`);

    const student = await open('student', 'es', `/courses/${courseId}/activities/${quizId}`);
    await student.getByRole('button', { name: new RegExp(`^${MESSAGES.es.assessment.reviewFeedback}`) }).click();
    const feedback = student.getByRole('region', { name: MESSAGES.es.assessment.feedbackHeading(1) });
    await feedback.waitFor();
    assert.equal((await feedback.innerText()).split(`${MESSAGES.es.assessment.yourAnswer} ${LABELS.es[0]}`).length - 1, 2, 'both answers are shown as Verdadero');
    await switchLocale(student, 'en');
    const english = student.getByRole('region', { name: MESSAGES.en.assessment.feedbackHeading(1) });
    assert.equal((await english.innerText()).split(`${MESSAGES.en.assessment.yourAnswer} ${LABELS.en[0]}`).length - 1, 2);
    await student.context().close();

    const staff = await open('instructor', 'es', `/courses/${courseId}/activities/${quizId}`);
    const r = MESSAGES.es.quiz.results;
    await staff.getByRole('button', { name: new RegExp(`^${r.view}\\b`) }).first().click();
    const detail = staff.locator('section[aria-labelledby="attempt-detail-heading"]');
    await detail.waitFor();
    const lines = (await detail.locator('ul > li').allInnerTexts()).map((line) => line.replace(/\s+/g, ' ').trim());
    assert.deepEqual(lines, [
      `☑ ${LABELS.es[0]} ${r.selected} ${r.correctAnswer}`,
      `☐ ${LABELS.es[1]}`,
      `☑ ${LABELS.es[0]} ${r.selected}`,
      `☐ ${LABELS.es[1]} ${r.correctAnswer}`,
    ]);
    await staff.context().close();
  });

  it('attempts saved before this change (the demo seed’s) are unchanged and shown in the interface language', async () => {
    const itil = (await apiGet<{ items: Array<{ id: string; code: string }> }>('instructor', '/courses?limit=100')).items.find((c) => c.code === 'ITIL4-F-2026-2-A')!.id;
    const sections = (await apiGet<{ items: Array<{ id: string }> }>('instructor', `/courses/${itil}/sections?limit=100`)).items;
    let quizId = '';
    for (const section of sections) {
      const found = (await apiGet<{ items: Array<{ id: string; type: string }> }>('instructor', `/courses/${itil}/sections/${section.id}/activities?limit=100`)).items.find((a) => a.type === 'quiz');
      if (found) quizId = found.id;
    }
    const results = `/courses/${itil}/activities/${quizId}/results`;
    const seeded = (await apiGet<{ items: Array<{ attemptId: string; student: { email: string } }> }>('instructor', `${results}?limit=100`)).items.filter((row) => /learner\.[ab]@/.test(row.student.email));
    assert.equal(seeded.length, 2, 'the two seeded learner attempts');
    const snapshot = async () => Promise.all(seeded.map((row) => apiGet<{ questions: ResultQuestion[] }>('instructor', `${results}/${row.attemptId}`)));
    const before = await snapshot();
    const trueFalse = (detail: { questions: ResultQuestion[] }) => detail.questions.find((question) => question.prompt.startsWith('An incident is the cause'))!;
    for (const detail of before) assert.deepEqual(trueFalse(detail).options.map(({ id, text }) => ({ id, text })), [{ id: 'true', text: 'True' }, { id: 'false', text: 'False' }]);

    for (const locale of ['es', 'en'] as const) {
      const r = MESSAGES[locale].quiz.results;
      const page = await open('instructor', locale, `/courses/${itil}/activities/${quizId}`);
      for (const row of seeded) {
        const chosen = trueFalse(before[seeded.indexOf(row)]!).selectedOptionIds[0]!;
        await page.getByRole('button', { name: new RegExp(row.student.email.replace(/[.]/g, '\\.')) }).click();
        const detail = page.locator('section[aria-labelledby="attempt-detail-heading"]');
        await detail.waitFor();
        const item = detail.locator('ol > li').filter({ hasText: 'An incident is the cause' });
        const lines = (await item.locator('ul > li').allInnerTexts()).map((line) => line.replace(/\s+/g, ' ').trim());
        const mark = (id: 'true' | 'false') => `${chosen === id ? '☑' : '☐'} ${LABELS[locale][id === 'true' ? 0 : 1]}${chosen === id ? ` ${r.selected}` : ''}${id === 'false' ? ` ${r.correctAnswer}` : ''}`;
        assert.deepEqual(lines, [mark('true'), mark('false')], `${row.student.email} ${locale}`);
        await detail.getByRole('button', { name: r.close }).click();
      }
      await page.context().close();
    }
    assert.deepEqual(await snapshot(), before, 'stored attempts, answers and grades are unchanged');
  });
});
